use super::*;

pub(crate) fn commit_samples(ev: &[Event], surface: Option<&str>) -> Vec<(String, f64)> {
    ev.iter()
        .filter_map(|e| match e {
            Event::Commit { surface: s, ms, .. } if surface.is_none_or(|w| w == s) => Some((s.clone(), *ms)),
            _ => None,
        })
        .collect()
}
